template:
use std::cell::RefCell;
use std::rc::Rc;

type Board = Rc<RefCell<Vec<i32>>>;

fn add_score(board: &Board, score: i32) {
    board⟦mut_access⟧.push(score);
}

fn snapshot(board: &Board) -> Vec<i32> {
    board⟦read_access⟧.clone()
}

fn main() {
    let scores: Board = Rc::new(RefCell::new(vec![10, 20]));
    let leaderboard = Rc::clone(&scores);
    add_score(&scores, 30);
    println!("{:?}", snapshot(&leaderboard));
}

tests:
#[test]
fn shares_mutation() {
    let scores: Board = Rc::new(RefCell::new(vec![10, 20]));
    let leaderboard = Rc::clone(&scores);
    add_score(&scores, 30);
    assert_eq!(snapshot(&leaderboard), vec![10, 20, 30]);
}
